var raw = $input.first().json;
var files = raw.files || [];
if (files.length === 0) {
  throw new Error('No files found. Raw API response: ' + JSON.stringify(raw));
}
return [{ json: files[0] }];

var docText = $input.first().json.data || '';

var systemPrompt = 'You are an operations intelligence AI for Service Push, a consulting company. Analyze weekly ops recaps and extract structured data. Return ONLY valid JSON, no markdown, no explanation.';

var userPrompt = 'Analyze this weekly operations recap and return structured JSON in EXACTLY this format with no extra text:
{
  "ai_summary": "2-3 sentence CEO-level summary of week health",
  "week_signal": "positive|neutral|negative|critical",
  "top_blockers": ["brief blocker description"],
  "overloaded_team": ["Full Name"],
  "metrics": {"critical": 0, "at_risk": 0, "blocked": 0, "completed": 0},
  "items": [{
    "title": "Short actionable title max 55 chars",
    "status": "critical|in_progress|blocked|completed",
    "priority": "high|medium|low",
    "owner": "Full Name or null",
    "client": "Client name or null",
    "section": "Section heading",
    "summary": "1-2 sentence description",
    "next_step": "Specific next action or null",
    "tags": []
  }]
}
Valid tags: blocker, revenue_risk, client_risk, overdue, needs_review
Status rules: critical=urgent blocking issue, in_progress=actively worked, blocked=waiting on external, completed=done this week

DOCUMENT:
' + docText.slice(0, 11000);

return [{
  json: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 4000,
    system: systemPrompt,
    messages: [{ role: 'user', content: userPrompt }]
  }
}];

var claudeResp = $input.first().json;
var info = $('Sort and Pick Most Recent').first().json;

function esc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

// Parse Claude response with fallback
var data = {ai_summary:'Analysis unavailable.',week_signal:'neutral',metrics:{critical:0,at_risk:0,blocked:0,completed:0},items:[],top_blockers:[],overloaded_team:[]};
try {
  var txt = claudeResp.content && claudeResp.content[0] ? claudeResp.content[0].text : '{}';
  txt = txt.replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim();
  data = JSON.parse(txt);
} catch(e) { /* use fallback */ }

var items = data.items || [];
var metrics = data.metrics || {};
var d = new Date(info.modifiedTime || info.createdTime || Date.now());
var dateStr = d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
var timeStr = d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZoneName:'short'});
var docLink = esc(info.webViewLink || '#');

// Group items by status
var groups = {critical:[],in_progress:[],blocked:[],completed:[]};
items.forEach(function(item){
  var s = item.status || 'in_progress';
  if(groups[s]) groups[s].push(item);
  else groups.in_progress.push(item);
});

// Unique owners for filter dropdown
var owners = [];
items.forEach(function(item){
  if(item.owner && owners.indexOf(item.owner) === -1) owners.push(item.owner);
});
owners.sort();

var signalMap = {positive:'&#x1F7E2;',neutral:'&#x1F7E1;',negative:'&#x1F534;',critical:'&#x1F6A8;'};
var signalLabel = {positive:'On Track',neutral:'Neutral',negative:'Needs Attention',critical:'Critical Week'};
var signal = data.week_signal || 'neutral';

function renderPriority(p){
  if(p==='high') return '<span class="pbadge ph">&#x1F534; HIGH</span>';
  if(p==='medium') return '<span class="pbadge pm">&#x1F7E1; MED</span>';
  return '<span class="pbadge pl">&#x1F7E2; LOW</span>';
}

function renderTags(tags){
  if(!tags||!tags.length) return '';
  var m={blocker:'<span class="tag tb">&#x26D4; Blocker</span>',revenue_risk:'<span class="tag tr2">&#x1F4B0; Revenue Risk</span>',client_risk:'<span class="tag tc">&#x1F6A8; Client Risk</span>',overdue:'<span class="tag to">&#x23F0; Overdue</span>',needs_review:'<span class="tag tnr">&#x1F440; Needs Review</span>'};
  return tags.map(function(t){return m[t]||'';}).join('');
}

function renderCard(item){
  var p = item.priority||'medium';
  var s = item.status||'in_progress';
  var ownerVal = esc(item.owner||'');
  var clientVal = esc(item.client||'');
  var ownerAttr = item.owner?'<span class="attr"><span class="ai2">&#x1F464;</span>'+ownerVal+'</span>':'';
  var clientAttr = item.client?'<span class="attr"><span class="ai2">&#x1F3E2;</span>'+clientVal+'</span>':'';
  var next = item.next_step?'<div class="nxt"><span class="narr">&#x2192;</span>'+esc(item.next_step)+'</div>':'';
  var tags = renderTags(item.tags);
  return '<div class="icard pr-'+p+' st-'+s+'" data-owner="'+ownerVal+'" data-priority="'+p+'" data-status="'+s+'">'
    +'<div class="ictop">'+renderPriority(p)+(item.section?'<span class="icsec">'+esc(item.section)+'</span>':'')+'</div>'
    +'<h3 class="ict">'+esc(item.title)+'</h3>'
    +(item.summary?'<p class="ics">'+esc(item.summary)+'</p>':'')
    +'<div class="icattrs">'+ownerAttr+clientAttr+'</div>'
    +next
    +(tags?'<div class="ictags">'+tags+'</div>':'')
  +'</div>';
}

function renderGroup(title,icon,grpItems,id,open){
  if(!grpItems.length) return '';
  var cards = grpItems.map(renderCard).join('');
  return '<div class="grp">'
    +'<div class="gh" onclick="tog(\''+id+'\')">'
      +'<div class="ghl">'+icon+' <span class="ghtitle">'+title+'</span><span class="ghcnt">'+grpItems.length+'</span></div>'
      +'<span id="gt-'+id+'">'+(open?'&#x25BC;':'&#x25B6;')+'</span>'
    +'</div>'
    +'<div class="gc" id="gc-'+id+'" style="display:'+(open?'grid':'none')+'">'+cards+'</div>'
  +'</div>';
}

var groupsHtml = ''
  + renderGroup('Critical Issues','&#x1F6A8;',groups.critical,'crit',true)
  + renderGroup('Blocked / Waiting','&#x23F3;',groups.blocked,'blk',true)
  + renderGroup('In Progress','&#x2699;',groups.in_progress,'prog',true)
  + renderGroup('Completed This Week','&#x2705;',groups.completed,'done',false);

var ownerOpts = '<option value="">All Owners</option>'
  + owners.map(function(o){return '<option value="'+esc(o)+'">'+esc(o)+'</option>';}).join('');

var blockersHtml = (data.top_blockers||[]).slice(0,5).map(function(b,i){
  return '<div class="bitem"><span class="bnum">'+(i+1)+'</span>'+esc(b)+'</div>';
}).join('');

var overloadedHtml = (data.overloaded_team||[]).map(function(n){
  return '<span class="olbadge">&#x26A0; '+esc(n)+'</span>';
}).join('');

var critN = metrics.critical || groups.critical.length;
var blkN = metrics.blocked || groups.blocked.length;
var riskN = metrics.at_risk || 0;
var progN = groups.in_progress.length;
var doneN = metrics.completed || groups.completed.length;

var css = ':root{--bg:#07090f;--s0:rgba(255,255,255,.04);--s1:rgba(255,255,255,.08);--b0:rgba(255,255,255,.07);--b1:rgba(255,255,255,.14);--tx:#dde1e9;--mt:#6b7a90;--red:#ef4444;--amb:#f59e0b;--blue:#3b82f6;--grn:#22c55e;--org:#f97316}'
+'*{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}'
+'body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,system-ui,sans-serif;background:var(--bg);color:var(--tx);min-height:100vh;line-height:1.6;font-size:14px}'
+'.hdr{position:sticky;top:0;z-index:100;background:rgba(7,9,15,.96);backdrop-filter:blur(20px);border-bottom:1px solid var(--b0)}'
+'.hi{display:flex;align-items:center;gap:12px;padding:0 24px;height:52px}'
+'.logo{display:flex;align-items:center;gap:9px;flex-shrink:0}'
+'.lm{width:30px;height:30px;background:linear-gradient(135deg,#3b82f6,#8b5cf6);border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:16px}'
+'.lt h1{font-size:14px;font-weight:700;letter-spacing:-.02em}'
+'.lt p{font-size:10px;color:var(--mt)}'
+'.hdiv{width:1px;height:22px;background:var(--b0);flex-shrink:0}'
+'.sbx{flex:1;max-width:320px}'
+'.sbx input{width:100%;padding:6px 12px;background:var(--s0);border:1px solid var(--b0);border-radius:7px;color:var(--tx);font-size:12px;outline:none;transition:all .2s}'
+'.sbx input:focus{background:var(--s1);border-color:rgba(99,102,241,.5)}'
+'.sbx input::placeholder{color:var(--mt)}'
+'.hright{display:flex;align-items:center;gap:8px;margin-left:auto}'
+'.upd{font-size:11px;color:var(--mt);white-space:nowrap}'
+'.btn{padding:5px 12px;border-radius:6px;border:none;cursor:pointer;font-size:12px;font-weight:500;transition:all .15s}'
+'.bto{background:transparent;color:var(--mt);border:1px solid var(--b0)}.bto:hover{color:var(--tx)}'
+'.btp{background:linear-gradient(135deg,#3b82f6,#6366f1);color:#fff}.btp:hover{filter:brightness(1.1)}'
+'.aibanner{margin:14px 24px;border-radius:12px;background:linear-gradient(135deg,rgba(99,102,241,.12),rgba(139,92,246,.08));border:1px solid rgba(99,102,241,.22);padding:14px 18px;display:flex;align-items:flex-start;gap:14px}'
+'.aico{width:36px;height:36px;background:linear-gradient(135deg,#6366f1,#8b5cf6);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0}'
+'.aicont{flex:1}'
+'.ailbl{font-size:10px;font-weight:700;color:#a78bfa;text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px}'
+'.aitxt{font-size:13px;color:var(--tx);line-height:1.55}'
+'.airight{display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0}'
+'.sigbadge{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:20px;font-size:11px;font-weight:600;background:rgba(255,255,255,.08);border:1px solid var(--b0)}'
+'.olbadge{display:inline-flex;align-items:center;gap:4px;font-size:11px;color:#fcd34d;background:rgba(245,158,11,.12);padding:2px 8px;border-radius:5px;margin:2px}'
+'.statsrow{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;padding:0 24px 12px}'
+'.sc{background:var(--s0);border:1px solid var(--b0);border-radius:9px;padding:12px 14px;cursor:pointer;transition:all .2s;text-align:center;position:relative;overflow:hidden}'
+'.sc:hover{background:var(--s1);transform:translateY(-1px);border-color:var(--b1)}'
+'.sn{font-size:24px;font-weight:700;margin-bottom:2px}'
+'.sl2{font-size:10px;color:var(--mt);text-transform:uppercase;letter-spacing:.05em}'
+'.frow{padding:0 24px 12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}'
+'.flab{font-size:10px;color:var(--mt);text-transform:uppercase;letter-spacing:.06em}'
+'.fpill{padding:4px 12px;border-radius:16px;border:1px solid var(--b0);background:transparent;color:var(--mt);font-size:11px;font-weight:500;cursor:pointer;transition:all .2s}'
+'.fpill:hover{color:var(--tx);border-color:var(--b1)}'
+'.fpill.act{color:#fff;border-color:transparent}'
+'.fpill.act.all{background:rgba(255,255,255,.1);color:var(--tx)}'
+'.fpill.act.high{background:#991b1b}.fpill.act.medium{background:#92400e}.fpill.act.low{background:#14532d}'
+'.fsel{padding:5px 10px;background:var(--s0);border:1px solid var(--b0);border-radius:7px;color:var(--tx);font-size:12px;outline:none;cursor:pointer}'
+'.fsel option{background:#111318}'
+'.blkbar{margin:0 24px 12px;border-radius:10px;background:rgba(239,68,68,.07);border:1px solid rgba(239,68,68,.2);padding:12px 16px}'
+'.blktitle{font-size:11px;font-weight:700;color:var(--red);text-transform:uppercase;letter-spacing:.07em;margin-bottom:8px}'
+'.bitem{display:flex;align-items:baseline;gap:8px;font-size:12px;color:#fca5a5;padding:3px 0;line-height:1.4}'
+'.bnum{width:16px;height:16px;background:rgba(239,68,68,.3);border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;flex-shrink:0}'
+'.main{padding:0 24px 48px}'
+'.grp{margin-bottom:16px}'
+'.gh{display:flex;align-items:center;justify-content:space-between;padding:9px 14px;background:var(--s0);border:1px solid var(--b0);border-radius:9px;cursor:pointer;user-select:none;transition:background .2s}'
+'.gh:hover{background:var(--s1)}'
+'.ghl{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:600}'
+'.ghcnt{background:var(--b0);padding:1px 8px;border-radius:10px;font-size:11px}'
+'.gc{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px}'
+'@media(max-width:1100px){.gc{grid-template-columns:repeat(2,1fr)}.statsrow{grid-template-columns:repeat(3,1fr)}}'
+'@media(max-width:700px){.gc{grid-template-columns:1fr}.statsrow{grid-template-columns:repeat(3,1fr)}.hi{flex-wrap:wrap;height:auto;padding:8px 16px}.sbx{max-width:100%;width:100%}}'
+'.icard{background:var(--s0);border:1px solid var(--b0);border-radius:10px;padding:13px;transition:all .2s;display:flex;flex-direction:column;gap:7px}'
+'.icard:hover{background:var(--s1);box-shadow:0 4px 20px rgba(0,0,0,.3);transform:translateY(-1px)}'
+'.icard.hidden{display:none}'
+'.icard.pr-high{border-left:3px solid var(--red)}'
+'.icard.pr-medium{border-left:3px solid var(--amb)}'
+'.icard.pr-low{border-left:3px solid var(--grn)}'
+'.icard.st-critical{background:rgba(239,68,68,.05)}'
+'.icard.st-blocked{background:rgba(249,115,22,.04)}'
+'.ictop{display:flex;align-items:center;justify-content:space-between;gap:6px}'
+'.icsec{font-size:10px;color:var(--mt);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:120px}'
+'.ict{font-size:13px;font-weight:600;color:var(--tx);line-height:1.35}'
+'.ics{font-size:11.5px;color:var(--mt);line-height:1.55}'
+'.icattrs{display:flex;gap:10px;flex-wrap:wrap}'
+'.attr{display:inline-flex;align-items:center;gap:4px;font-size:11px;color:var(--mt)}'
+'.ai2{font-size:12px}'
+'.nxt{font-size:11.5px;color:#93c5fd;display:flex;align-items:flex-start;gap:5px}'
+'.narr{color:#60a5fa;flex-shrink:0}'
+'.ictags{display:flex;gap:5px;flex-wrap:wrap}'
+'.tag{font-size:10px;font-weight:600;padding:2px 7px;border-radius:5px}'
+'.tb{background:rgba(239,68,68,.15);color:#fca5a5}'
+'.tr2{background:rgba(34,197,94,.12);color:#86efac}'
+'.tc{background:rgba(245,158,11,.12);color:#fcd34d}'
+'.to{background:rgba(249,115,22,.12);color:#fdba74}'
+'.tnr{background:rgba(139,92,246,.12);color:#c4b5fd}'
+'.pbadge{font-size:10px;font-weight:700;padding:2px 7px;border-radius:5px;letter-spacing:.03em;white-space:nowrap}'
+'.ph{background:rgba(239,68,68,.18);color:#fca5a5}'
+'.pm{background:rgba(245,158,11,.18);color:#fcd34d}'
+'.pl{background:rgba(34,197,94,.18);color:#86efac}'
+'.nores{display:none;text-align:center;padding:48px;color:var(--mt)}'
+'.footer{border-top:1px solid var(--b0);padding:14px 24px;display:flex;align-items:center;justify-content:space-between;font-size:11px;color:var(--mt)}'
+'.footer a{color:var(--blue);text-decoration:none}.footer a:hover{text-decoration:underline}'
+'::-webkit-scrollbar{width:4px}::-webkit-scrollbar-thumb{background:rgba(255,255,255,.1);border-radius:2px}'
+'@media print{.hdr{position:static}.frow,.hright{display:none}}';

var html = '<!DOCTYPE html><html lang="en"><head>'
+'<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
+'<title>Ops Command Center &middot; Service Push</title>'
+'<style>'+css+'</style></head><body>'
+'<header class="hdr"><div class="hi">'
+'<div class="logo"><div class="lm">&#x1F4CA;</div><div class="lt"><h1>Weekly Ops Command Center</h1><p>Service Push &middot; AI-Powered</p></div></div>'
+'<div class="hdiv"></div>'
+'<div class="sbx"><input type="text" id="srch" placeholder="Search items, owners, clients..."></div>'
+'<div class="hright"><span class="upd">'+dateStr+'</span>'
+'<button class="btn bto" onclick="window.print()">Print</button>'
+'<button class="btn btp" onclick="location.reload()">&#x21BB; Refresh</button>'
+'</div></div></header>'

+'<div class="aibanner">'
+'<div class="aico">&#x1F9E0;</div>'
+'<div class="aicont"><div class="ailbl">&#x2728; AI Weekly Intelligence</div>'
+'<div class="aitxt">'+esc(data.ai_summary)+'</div></div>'
+'<div class="airight">'
+'<span class="sigbadge">'+(signalMap[signal]||'&#x1F7E1;')+' '+(signalLabel[signal]||'Neutral')+'</span>'
+(overloadedHtml?'<div style="font-size:11px;color:var(--amb)">&#x26A0; Overloaded: '+overloadedHtml+'</div>':'')
+'</div></div>'

+'<div class="statsrow">'
+'<div class="sc" onclick="filterSt(\'critical\')"><div class="sn" style="color:var(--red)">'+critN+'</div><div class="sl2">&#x1F6A8; Critical</div></div>'
+'<div class="sc" onclick="filterSt(\'blocked\')"><div class="sn" style="color:var(--org)">'+blkN+'</div><div class="sl2">&#x23F3; Blocked</div></div>'
+'<div class="sc"><div class="sn" style="color:var(--amb)">'+riskN+'</div><div class="sl2">&#x26A0; At Risk</div></div>'
+'<div class="sc" onclick="filterSt(\'in_progress\')"><div class="sn" style="color:var(--blue)">'+progN+'</div><div class="sl2">&#x2699; In Progress</div></div>'
+'<div class="sc" onclick="filterSt(\'completed\')"><div class="sn" style="color:var(--grn)">'+doneN+'</div><div class="sl2">&#x2705; Completed</div></div>'
+'</div>'

+'<div class="frow">'
+'<span class="flab">Priority:</span>'
+'<button class="fpill act all" data-p="all">All</button>'
+'<button class="fpill high" data-p="high">&#x1F534; High</button>'
+'<button class="fpill medium" data-p="medium">&#x1F7E1; Medium</button>'
+'<button class="fpill low" data-p="low">&#x1F7E2; Low</button>'
+'<div class="hdiv"></div>'
+'<span class="flab">Owner:</span>'
+'<select class="fsel" id="ownersel"><option value="">All Owners</option>'+ownerOpts+'</select>'
+'</div>'

+(blockersHtml?'<div class="blkbar"><div class="blktitle">&#x1F6AB; Top Blockers Requiring Attention</div>'+blockersHtml+'</div>':'')

+'<main class="main"><div id="allgrps">'+groupsHtml+'</div>'
+'<div class="nores" id="nores"><div style="font-size:36px">&#x1F50D;</div><p style="margin-top:8px">No items match your filters</p></div>'
+'</main>'

+'<footer class="footer">'
+'<span>&#x1F4C4; <a href="'+docLink+'" target="_blank" rel="noopener">7 Day Recap &mdash; Google Docs</a></span>'
+'<span>Powered by n8n &amp; Claude AI &middot; '+dateStr+' &middot; '+timeStr+'</span>'
+'</footer>'

+'<script>'
+'var curP="all",curSt="all",allCards=Array.from(document.querySelectorAll(".icard")),nores=document.getElementById("nores");'
+'function go(){'
+'var q=document.getElementById("srch").value.toLowerCase().trim();'
+'var ow=document.getElementById("ownersel").value;'
+'var vis=0;'
+'allCards.forEach(function(c){'
+'var ok=(curP==="all"||c.dataset.priority===curP)&&(curSt==="all"||c.dataset.status===curSt)&&(!ow||c.dataset.owner===ow)&&(!q||c.textContent.toLowerCase().indexOf(q)>=0);'
+'c.classList.toggle("hidden",!ok);if(ok)vis++;'
+'});'
+'nores.style.display=vis===0?"block":"none";'
+'}'
+'function filterSt(s){curSt=s;curP="all";document.querySelectorAll(".fpill").forEach(function(p){p.classList.remove("act");});document.querySelector(".fpill.all").classList.add("act");go();}'
+'document.querySelectorAll(".fpill").forEach(function(p){'
+'p.addEventListener("click",function(){document.querySelectorAll(".fpill").forEach(function(x){x.classList.remove("act");});p.classList.add("act");curP=p.dataset.p;curSt="all";go();});'
+'});'
+'document.getElementById("srch").addEventListener("input",go);'
+'document.getElementById("ownersel").addEventListener("change",go);'
+'function tog(id){var gc=document.getElementById("gc-"+id),gt=document.getElementById("gt-"+id);if(!gc||!gt)return;if(gc.style.display==="none"){gc.style.display="grid";gt.innerHTML="&#x25BC;";}else{gc.style.display="none";gt.innerHTML="&#x25B6;";}}'  
+'<\/script></body></html>';

return [{json:{html:html}}];
